  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "A piperidine-ether aryl analogue with a basic center showed very high brain-to-plasma partitioning (16:1) in mice after oral dosing, demonstrating that this chemotype can achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A closely related piperidine-ether quinazoline showed 5- to 6-fold higher brain than plasma exposure in mice, supporting robust BBB penetration for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A heteroaromatic ether with a basic center achieved an unbound brain-to-blood ratio of 0.99 in rats, indicating good brain uptake despite polar functionality.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A piperidine-containing ether-linked aromatic radiotracer showed rapid high brain uptake in rat and monkey PET, supporting CNS access for similar piperidine-ether scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "An acetamide analogue with a piperidine-ether linker had a brain-to-blood ratio consistent with free passage across the BBB in rats.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental analogues, despite low Morgan similarities, show positive CNS exposure/brain penetration; the query shares the key piperidine-ether aryl motif and has no obvious extreme polarity or efflux liability, supporting a pass for meaningful CNS access.",
